argv:
$ErrorActionPreference='Stop';
$repo='E:\WebAIBridge';
Push-Location $repo;
$head=[string](git rev-parse HEAD);
$branch=[string](git branch --show-current);
$dirty=@(git status --porcelain);
Pop-Location;
$head=$head.Trim();$branch=$branch.Trim();
$cut='E:\WebAIBridge\app\data\projects-live-control-plane-cutover-r42.json';
$cutState=$null;if(Test-Path $cut){try{$cutState=Get-Content $cut -Raw|ConvertFrom-Json}catch{}}
$procs=@(Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -match 'r42-cutover\.ps1' -and $_.ProcessId -ne $PID } | Select-Object ProcessId,Name,CommandLine);
$health=Get-Content 'E:\pc-github-relay\.pc-relay\health.json' -Raw|ConvertFrom-Json;
[pscustomobject]@{
 head=$head;branch=$branch;detached=([string]::IsNullOrWhiteSpace($branch));dirtyCount=$dirty.Count;
 cutoverExists=(Test-Path $cut);
 cutoverStatus=if($cutState){$cutState.status}else{''};
 holdActive=if($cutState){$cutState.holdActive}else{$false};
 activeCutoverProcesses=@($procs);
 relayReconciliationRequired=$health.reconciliation_required;
 relayLastError=$health.last_error
}|ConvertTo-Json -Depth 5 -Compress
